(static function()use($db,$f,$key,$assert,$denied,$tables):void{
    $tag='Own forty original cents %_[]';$account=$f->createAccount($tag,'offline','10','2020-01-01');$entry=$f->createEntry(['kind'=>'income','category'=>'general','amount'=>'0.41','description'=>$tag,'document_date'=>'2026-01-01','due_date'=>'2026-01-01'],$key());$ids=[];
    for($i=0;$i<41;++$i){$source=$f->createTransaction(['account'=>$account,'direction'=>'income','amount'=>'0.01','booked_on'=>'2026-01-23','description'=>$tag.' '.$i],$key());$f->allocate($source,(int)$f->transactionDetail($source)['version'],$entry,(int)$f->entry($entry)['version'],'0.01',$key());$links=$f->allocations($entry);$ids[]=end($links)['id'];}
    // Use actual source identities; allocation display ordering is not creation ordering.
