    for($page=1;$page<=3;++$page){$result=$f->partialReturnCandidatesPage($counter,$page,$tag);$assert($result['total']===41&&$result['pages']===3&&$result['page']===$page&&count($result['rows'])===($page===3?1:20),'actual forty-one-source catalogue preserves literal punctuation and exact page '.$page);array_push($seen,...array_column($result['rows'],'allocation_id'));}
    $assert(count(array_unique($seen))===41&&array_diff($seen,$ids)===[]&&$before===ownOriginalDatabaseHash($db,$tables),'three source pages expose every original once without changing any whole row');$amounts=array_map(static fn(string$id):array=>['allocation_id'=>$id,'amount'=>'0.01'],array_slice($ids,0,40));$tooMany=array_map(static fn(string$id):array=>['allocation_id'=>$id,'amount'=>'0.01'],$ids);$denied(fn()=>$f->partialReturnReview($counter,$tooMany,'Own actual source boundary'),'forty-one actual source choices cannot pass the forty-source review boundary');$assert($before===ownOriginalDatabaseHash($db,$tables),'rejected forty-one-source review preserves every existing row');
    $rawAllocations=static function()use($db,$entry):array{$q=$db->prepare('SELECT * FROM finance_allocations WHERE entry_id=? ORDER BY id');$q->execute([$entry]);return $q->fetchAll();};$oldAllocations=$rawAllocations();$reason='Own actual forty original cents returned';$review=$f->partialReturnReview($counter,$amounts,$reason);$args=[$counter,(int)$review['review']['counter']['version'],$amounts,$reason,$key(),$review['hash'],true];$first=$f->returnPaymentParts(...$args);$current=$f->entry($entry);$assert(count($f->partialReturnOriginal($counter,$first['id'])['items'])===40&&$current['allocated_cents']===1&&$current['remaining_cents']===40&&$rawAllocations()===$oldAllocations&&$f->transactionDetail($counter)['remaining_cents']===0,'forty actual one-cent sources return atomically while every original positive allocation remains exact');
    $voidReason='Own exact forty fragmented cents restored';$review=$f->partialReturnRevocationReview($counter,$first['id'],$voidReason);$f->revokePaymentParts($counter,$first['id'],$voidReason,$key(),$review['hash'],true);$current=$f->entry($entry);$assert($current['allocated_cents']===41&&$current['remaining_cents']===0&&$rawAllocations()===$oldAllocations&&$f->transactionDetail($counter)['remaining_cents']===40,'explicit revocation restores all forty original cent fragments and only releases the existing counter classification');$before=ownOriginalDatabaseHash($db,$tables);$replay=$f->returnPaymentParts(...$args);$assert($replay['replayed']&&!$replay['active']&&$before===ownOriginalDatabaseHash($db,$tables),'forty-item original replay remains pure and cannot reactivate fragmented returned funding');
})();
